body.onloadscript:

    targetId = Sepoa.request.UPLOAD_ID;
    house_code = Sepoa.request.HOUSE_CODE;
    house_name = Sepoa.request.HOUSE_NAME;
    company_code = Sepoa.params.COMPANY_CODE;
    formObj.hideItem('searchImg');
    formObj.setValue('HOUSE_NAME', house_name);
    formObj.setValue('HOUSE_CODE', house_code);
    formObj.setValue('COMPANY_CODE', company_code);
    colIdxCompany = gridObj.getColIndexById('COMPANY_CODE');
	colIdxDept = gridObj.getColIndexById('DEPT');
	colIdxDeptNameLoc = gridObj.getColIndexById('DEPT_NAME_LOC');
	colIdxDeptNameEng = gridObj.getColIndexById('DEPT_NAME_ENG');
	colIdxDeptNameJp = gridObj.getColIndexById('DEPT_NAME_JP');
	colIdxDeptNameCn = gridObj.getColIndexById('DEPT_NAME_CN');
	colIdxParentDept = gridObj.getColIndexById('PARENT_DEPT');
	colIdxParentDeptName = gridObj.getColIndexById('PARENT_DEPT_NAME');
	colIdxManagerId = gridObj.getColIndexById('MANAGER_ID');
	colIdxManagerName = gridObj.getColIndexById('MANAGER_NAME');

userscript.function:

	if (gridObj.getRowsNum() == 0) {
		gridObj.loadExcel({});
	} else {
    	Confirm(Sepoa.cache.text.get('DF_001.doUpload'), function(result) {
        	if (result) {
            	gridObj.loadExcel({});
        	}
    	});
    }


        	var company_codes = [];
        	var parent_depts = [];
        	var manager_ids = [];
            for (var i = 0; i < gridObj.getRowsNum(); i++) {
                gridObj.cells2(i, gridObj.getColIndexById('ROW_NUM')).setValue(gridObj.getRowId(i));
                company_codes.push(gridObj.cells2(i, colIdxCompany).getValue());
                parent_depts.push(gridObj.cells2(i, colIdxParentDept).getValue());
                manager_ids.push(gridObj.cells2(i, colIdxManagerId).getValue());
            }

            var params = {
                HOUSE_CODE: formObj.getValue('HOUSE_CODE'),
                COMPANY_CODES: company_codes,
                PARENT_DEPTS: parent_depts,
                MANAGER_IDS: manager_ids
            };

            doServiceAjax('sepoa.svc.info.SepoaInfoUploadService', 'CONNECTION', 'searchDeptList', params, function(so){
	        	if (so.status == 1){
	        		var gridData = JSON.parse(so.param.params);
	        		for (var i = 0; i < gridObj.getRowsNum(); i++) {
	        			if (Sepoa.info.LANGUAGE == 'KO') {
		                	gridObj.cells2(i, colIdxParentDeptName).setValue(gridData[i].PARENT_DEPT_NAME_LOC);
		                	gridObj.cells2(i, colIdxManagerName).setValue(gridData[i].MANAGER_NAME_LOC);
	        			} else if (Sepoa.info.LANGUAGE == 'JA') {
	        				gridObj.cells2(i, colIdxParentDeptName).setValue(gridData[i].PARENT_DEPT_NAME_JP);
		                	gridObj.cells2(i, colIdxManagerName).setValue(gridData[i].MANAGER_NAME_ENG);
	        			} else if (Sepoa.info.LANGUAGE == 'ZH') {
	        				gridObj.cells2(i, colIdxParentDeptName).setValue(gridData[i].PARENT_DEPT_NAME_CN);
		                	gridObj.cells2(i, colIdxManagerName).setValue(gridData[i].MANAGER_NAME_ENG);
	        			} else {
	        				gridObj.cells2(i, colIdxParentDeptName).setValue(gridData[i].PARENT_DEPT_NAME_ENG);
		                	gridObj.cells2(i, colIdxManagerName).setValue(gridData[i].MANAGER_NAME_ENG);
	        			}
		            }
	        	} else {
	        		Alert(so.message);
	        	}
	        });


if (gridObj.getRowsNum() < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.0004'));
    return;
}
gridObj.allRowsChecked('SELECTED', true);

var selectedRow = gridObj.getGridChangedRows("SELECTED");
if (!gridObj.validate()) {
    Alert(Sepoa.cache.text.get('MESSAGE.0002'));
    return;
}

Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
    if (result) {
        gridObj.editStop();
        dataOutput.setValue('TARGET_HOUSE', getOAObject('DF_002', 'formObj').getValue('HOUSE_CODE'));
        dataOutput.setValue('TARGET_COMPANY', getOAObject('DF_002', 'formObj').getValue('COMPANY_CODE'));
        var params = [];
        params.push('mode=doSave');
        params.push('PROCESS_ID=sepoa.svc.info.SepoaInfoUploadService');
        params.push('METHOD=doDeptSave');

        gridObj.postTransaction(window.CONTEXT_NAME+'/SepoaGrid.sux', params, 'SELECTED');
    }
});


var status = obj.status;
var message = obj.message;
var gridData = JSON.parse(obj.params);

for (var i = 0; i < gridData.length; i++) {
    gridObj.cells(gridData[i].ROW_NUM, gridObj.getColIndexById('STATUS')).setValue(gridData[i].STATUS);
    gridObj.cells(gridData[i].ROW_NUM, gridObj.getColIndexById('ERR_MSG')).setValue(gridData[i].ERR_MSG);
}
Alert(Sepoa.cache.text.get('DF_001.MSG_001'));


var selectedRow = gridObj.getGridChangedRows("SELECTED");
if (selectedRow.length < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004'));
    return;
}
Confirm(Sepoa.cache.text.get('DF_001.doDelete'), function(result) {
    if (result) {
        for (var i = 0; i < selectedRow.length; i++)
            gridObj.deleteRow(selectedRow[i]);
    }
});


targetId = id;
var fileId = 'DEPARTMENT_MASTER_Template.xlsx'
sepoaExcelProcessor('down', 'sepoa.svc.info.SepoaInfoUploadService', 'doDeptExcelDownload', null, fileId);


